/// Trace directed graph mutations and queries with typed weight output.
fn putI64(out:[*]u8,index:usize,value:i64)void{const bits:u64=@bitCast(value);for(0..8)|b|out[index*8+b]=@truncate(bits>>@intCast(8*b));}
pub export fn graph_lua_directed_weighted(input:[*c]const i64,length:usize,output:[*c]u8,capacity:usize)i64{
 if(input==null or length<2)return -1;const nv=input[0];const ov=input[1];if(nv<1 or nv>16 or ov<0 or ov>63)return -1;const n:usize=@intCast(nv);const ops:usize=@intCast(ov);if(length!=2+4*ops)return -1;var kind:[256]i64=@splat(0);var weight:[256]i64=@splat(0);var rtype:[63]i64=@splat(0);var rvalue:[63]i64=@splat(0);
 for(0..ops)|i|{const op=input[2+4*i];const av=input[3+4*i];const bv=input[4+4*i];const v=input[5+4*i];if(op<0 or op>5 or av<0 or av>=nv or bv<0 or bv>=nv)return -1;const p:usize=@intCast(av*16+bv);if(op==0){if(v< -1000 or v>1000)return -1;kind[p]=2;weight[p]=v;rtype[i]=-1;}else if(op==1){if(v!=0)return -1;kind[p]=1;weight[p]=0;rtype[i]=-1;}else if(op==2){if(v!=0)return -1;kind[p]=0;weight[p]=0;rtype[i]=-1;}else if(op==3){if(v!=0 or kind[p]!=0)return -1;kind[p]=1;weight[p]=0;rtype[i]=-1;}else if(op==4){if(v!=0)return -1;rtype[i]=kind[p];rvalue[i]=if(kind[p]==2)weight[p] else 0;}else{if(v!=0)return -1;rtype[i]=if(kind[p]!=0)1 else 0;}}
 var edges:usize=0;for(0..n)|a|{for(0..n)|b|{if(kind[a*16+b]!=0)edges+=1;}}const words=2+2*ops+4*edges;if(output==null or capacity<words*8)return -2;var k:usize=0;putI64(output,k,@intCast(ops));k+=1;for(0..ops)|i|{putI64(output,k,rtype[i]);k+=1;putI64(output,k,rvalue[i]);k+=1;}putI64(output,k,@intCast(edges));k+=1;for(0..n)|a|{for(0..n)|b|{const p=a*16+b;if(kind[p]!=0){putI64(output,k,@intCast(a));k+=1;putI64(output,k,@intCast(b));k+=1;putI64(output,k,kind[p]);k+=1;putI64(output,k,weight[p]);k+=1;}}}return @intCast(words*8);
}
